(()=>{
const M=WeeklyDrafts,workflow='https://api.github.com/repos/marzlo/Economist/actions/workflows/weekly.yml',content='https://api.github.com/repos/marzlo/Economist/contents/';
const host=document.createElement('details');host.id='weekly-manager';host.innerHTML=`<summary>管理週報草稿</summary><div class="weekly-manager-body"><p class="muted">採人工整理方式：在對話中請我整理上週記事，確認內容後再發布到網站。這裡可預覽、修改已整理的草稿；不需要 AI API 金鑰，也不會自動呼叫付費 AI 服務。草稿保存在這個公開儲存庫。</p><div class="weekly-manager-controls"><button id="weekly-reload-drafts">查看待確認草稿</button></div><p id="weekly-job-message" role="status" class="muted"></p><div id="weekly-draft-list"></div></div>`;document.getElementById('weekly-review').append(host);
const archive=document.createElement('details');archive.id='weekly-published-archive';archive.innerHTML='<summary>歷次週報</summary><div></div>';host.before(archive);
fetch('weekly/index.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(20000)}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(catalog=>{const entries=(catalog.issues||[]).filter(i=>/^weekly\/\d{4}-\d{2}-\d{2}\/$/.test(i.path));archive.querySelector('summary').textContent='歷次週報（'+entries.length+'）';archive.querySelector('div').innerHTML=entries.map(i=>`<a href="${esc(i.path)}">${esc(i.start)}—${esc(i.end)} · ${esc(i.title)}</a>`).join('')}).catch(()=>archive.querySelector('div').textContent='歷次週報清單暫時讀取失敗，可先閱讀上方這一期。');
const dialog=document.createElement('dialog');dialog.id='weekly-draft-editor';dialog.innerHTML=`<div class="weekly-editor-heading"><h2>週報草稿預覽</h2><button id="weekly-editor-close" type="button" aria-label="關閉草稿預覽">✕</button></div><p id="weekly-editor-meta" class="muted"></p><details id="weekly-edit-fields"><summary>修改標題、敘事與分類文字</summary><div id="weekly-fields"></div></details><div class="weekly-draft-actions"><button id="weekly-preview">重新預覽修改</button><button id="weekly-save">儲存草稿</button><button id="weekly-publish">發布這一期</button></div><p id="weekly-editor-message" role="status" class="muted"></p><iframe id="weekly-preview-frame" title="週報草稿預覽" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox"></iframe>`;document.body.append(dialog);
const get=id=>document.getElementById(id),message=text=>get('weekly-job-message').textContent=text,editorMessage=text=>get('weekly-editor-message').textContent=text;
const taipeiToday=M.dateString(new Date());
let draft=null,sha=null,template=null,dirty=false,running=false,timer=null;
const needToken=()=>{if(token())return true;message('請先設定 GitHub 權杖，需具備本儲存庫 Contents 與 Actions 的 Read and write 權限。');get('sync-settings').click();return false};
async function read(path,optional=false){const r=await fetch(content+path+'?ref=main&t='+Date.now(),{headers:headers(),cache:'no-store',signal:AbortSignal.timeout(20000)});if(optional&&r.status===404)return null;if(!r.ok)throw Error('讀取草稿失敗（'+r.status+'），請檢查同步權杖權限');const data=await r.json();return {sha:data.sha,value:decodeIssues(data.content)}}
function busy(value){running=value;get('weekly-publish').disabled=value}
async function list(){if(!needToken())return;try{const result=await read('_weekly/drafts/index.json',true),items=result?.value||[];get('weekly-draft-list').innerHTML=items.length?items.map(i=>`<button class="weekly-open-draft" data-week="${esc(i.start)}">${esc(i.start)}—${esc(i.end)} · 預覽草稿</button>`).join(''):'<p class="muted">尚無待確認草稿。可在對話中說「幫我整理上週記事」，整理完成後再預覽發布。</p>';get('weekly-draft-list').querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>open(b.dataset.week))}catch(e){message(e.message)}}
function fields(){get('weekly-fields').innerHTML=`<label>標題<input id="weekly-title-input" maxlength="70" value="${esc(draft.title)}"></label><label>副標<textarea id="weekly-subtitle-input" rows="2">${esc(draft.subtitle)}</textarea></label><label>本週導讀<textarea id="weekly-intro-input" rows="4">${esc(draft.intro)}</textarea></label>${draft.chapters.map((c,i)=>`<fieldset class="weekly-chapter-fields" data-chapter="${i}"><legend>${esc(c.number)} · ${esc(c.name)}（${c.ids.length} 篇記事）</legend>${[['name','分類名稱',1],['title','章節標題',2],['summary','敘事整理',4],['observation','整理後的觀察',3],['question','延伸問題',2]].map(([key,label,rows])=>`<label>${label}<textarea data-key="${key}" rows="${rows}">${esc(c[key])}</textarea></label>`).join('')}<label>關係圖概念（每行一項，2–4 項）<textarea data-key="captions" rows="4">${esc(c.captions.join('\n'))}</textarea></label></fieldset>`).join('')}<label>原文引句來源<select id="weekly-quote-note">${draft.notes.map(n=>`<option value="${esc(n.id)}" ${draft.quote?.noteId===n.id?'selected':''}>${esc(n.statDate+' '+n.title)}</option>`).join('')}</select></label><label>逐字引句（留白移除）<textarea id="weekly-quote-input" rows="3">${esc(draft.quote?.text||'')}</textarea></label><label>下次閱讀的問題（每行一題，最多 4 題）<textarea id="weekly-questions-input" rows="4">${esc(draft.questions.join('\n'))}</textarea></label>`;get('weekly-fields').oninput=()=>{dirty=true;editorMessage('尚有未儲存的修改；可先重新預覽。')}}
function edited(){const next=structuredClone(draft);next.title=get('weekly-title-input').value.trim();next.subtitle=get('weekly-subtitle-input').value.trim();next.intro=get('weekly-intro-input').value.trim();get('weekly-fields').querySelectorAll('[data-chapter]').forEach(el=>{const c=next.chapters[Number(el.dataset.chapter)];el.querySelectorAll('[data-key]').forEach(input=>c[input.dataset.key]=input.dataset.key==='captions'?input.value.split('\n').map(s=>s.trim()).filter(Boolean):input.value.trim())});const quote=get('weekly-quote-input').value.trim();next.quote=quote?{noteId:get('weekly-quote-note').value,text:quote}:null;next.questions=get('weekly-questions-input').value.split('\n').map(s=>s.trim()).filter(Boolean);return M.validate(next)}
function preview(){try{get('weekly-preview-frame').srcdoc=M.previewDocument(template,edited(),document.baseURI);editorMessage(dirty?'預覽已更新，修改尚未儲存。':'這是草稿，尚未發布。')}catch(e){editorMessage(e.message)}}
async function open(week){if(dirty&&!confirm('目前有未儲存的修改，要捨棄並開啟另一份草稿嗎？'))return;try{const result=await read('_weekly/drafts/'+week+'.json');draft=M.validate(result.value);sha=result.sha;dirty=false;if(!template){const r=await fetch('weekly/template.html?v=1',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('預覽範本讀取失敗');template=await r.text()}fields();get('weekly-edit-fields').open=false;get('weekly-editor-meta').textContent=draft.start+'—'+draft.end+' · '+draft.notes.length+' 篇記事 · 整理於 '+draft.compiledAt;preview();dialog.showModal()}catch(e){message(e.message)}}
async function save(){const next=edited();next.revision=crypto.randomUUID();const current=await read('_weekly/drafts/'+draft.start+'.json');if(current.sha!==sha)throw Error('草稿已被重新產生或由其他裝置修改，請重新載入並確認後再儲存');const r=await fetch(content+'_weekly/drafts/'+draft.start+'.json',{method:'PUT',headers:{...headers(),'Content-Type':'application/json'},signal:AbortSignal.timeout(20000),body:JSON.stringify({message:'Edit weekly reflection draft',content:encodeIssues(next),sha,branch:'main'})});if(!r.ok)throw Error(r.status===409?'草稿有衝突，請重新載入確認':'儲存草稿失敗（'+r.status+'）');sha=(await r.json()).content.sha;draft=next;dirty=false;editorMessage('草稿已儲存，尚未發布。');return next}
function lockEditor(value){dialog.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=value)}
get('weekly-save').onclick=async()=>{lockEditor(true);try{await save();preview();editorMessage('草稿已儲存，尚未發布。')}catch(e){editorMessage(e.message)}finally{lockEditor(false);get('weekly-publish').disabled=running}};
get('weekly-preview').onclick=preview;get('weekly-editor-close').onclick=()=>{if(!dirty||confirm('尚有未儲存的修改，確定關閉並捨棄嗎？')){dirty=false;dialog.close()}};
dialog.addEventListener('cancel',e=>{if(dirty&&!confirm('尚有未儲存的修改，確定關閉並捨棄嗎？'))e.preventDefault();else dirty=false});
async function start(week,revision){const operation='publish';if(running)return;if(!needToken())return;if(localStorage.getItem('economist-sync-pending')){message('還有記事尚未同步，請先完成 GitHub 同步再發布。');return}const parsed=new Date(week+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(week)||!Number.isFinite(parsed.getTime())||M.monday(week)!==week||week>M.monday(taipeiToday)){message('請選擇本週或更早一週的星期一。');return}const state={requestId:crypto.randomUUID(),operation,week,started:Date.now()};busy(true);try{await actionRequest(workflow+'/dispatches',{method:'POST',body:JSON.stringify({ref:'main',inputs:{operation,week,revision,request_id:state.requestId}})});localStorage.setItem('economist-weekly-run',JSON.stringify(state));message('已送出發布，等待 GitHub 執行…');monitor(state)}catch(e){busy(false);message(e.message)}}
async function monitor(state){try{if(Date.now()-state.started>20*60*1000)throw Error('週報處理時間較長，請到 GitHub Actions 查看執行紀錄');let run;if(state.runId)run=await actionRequest('https://api.github.com/repos/marzlo/Economist/actions/runs/'+state.runId);else{const list=await actionRequest(workflow+'/runs?event=workflow_dispatch&per_page=20');run=list.workflow_runs.find(r=>(r.display_title||'').includes(state.requestId));if(run){state.runId=run.id;localStorage.setItem('economist-weekly-run',JSON.stringify(state))}}if(run?.status==='completed'){localStorage.removeItem('economist-weekly-run');busy(false);if(run.conclusion!=='success'){message('週報發布失敗，現有正式版保留。請查看 GitHub Actions 執行紀錄。');const a=document.createElement('a');a.href=run.html_url;a.target='_blank';a.rel='noopener';a.textContent=' 查看執行紀錄 ↗';get('weekly-job-message').append(a);return}message('這一期已發布並完成部署；重新載入頁面即可看到。');editorMessage('已發布並完成部署。');return}message((run?.status==='in_progress'?'正在'+'建立正式週報與部署':'等待 GitHub 執行')+' · '+Math.floor((Date.now()-state.started)/1000)+' 秒');timer=setTimeout(()=>monitor(state),5000)}catch(e){busy(false);message(e.message+'；工作流程可能仍在 GitHub 執行，可重新整理後繼續查看。')}}
get('weekly-reload-drafts').onclick=list;
get('weekly-publish').onclick=async()=>{if(running)return;try{edited();if(!confirm('發布「'+get('weekly-title-input').value+'」？\n將更新 '+draft.start+' 這一期的正式頁面；若已發布，會以這次確認的內容替換。'))return;lockEditor(true);if(dirty)await save();await start(draft.start,draft.revision)}catch(e){editorMessage(e.message)}finally{lockEditor(false);get('weekly-publish').disabled=running}};
host.addEventListener('toggle',()=>{if(host.open&&token()&&!get('weekly-draft-list').children.length)list()});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
try{const state=JSON.parse(localStorage.getItem('economist-weekly-run'));if(state&&state.operation!=='publish'){localStorage.removeItem('economist-weekly-run')}else if(state&&token()){host.open=true;busy(true);monitor(state)}}catch{}
})();
